node -e "
const Database = require('/tmp/node_modules/better-sqlite3');
const db = new Database('/workspace/world.db');

// Find the right table names for customer/payment info
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
const customerTables = tables.filter(t => t.name.includes('user') || t.name.includes('customer') || t.name.includes('payment') || t.name.includes('account'));
console.log('Relevant tables:', customerTables.map(t => t.name));

// Check shopping-related tables
for (const t of tables) {
  if (['products','orders','order_items','carts','cart_items','promotions','warranties'].includes(t.name)) continue;
  // look for user_d3d5d0c8 in any table
  try {
    const rows = db.prepare('SELECT * FROM ' + t.name + ' WHERE customer_id = ? OR user_id = ?').all('user_d3d5d0c8', 'user_d3d5d0c8');
    if (rows.length > 0) {
      console.log('\n=== ' + t.name + ' (matches for user_d3d5d0c8) ===');
      rows.forEach(r => console.log(JSON.stringify(r)));
    }
  } catch(e) {}
}

// Also check rt_users or similar
for (const t of tables) {
  if (t.name.startsWith('rt_') || t.name.includes('user') || t.name.includes('shopper')) {
    const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
    console.log('\n' + t.name + ' columns:', cols.map(c => c.name));
    const sample = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 3').all();
    sample.forEach(r => console.log(JSON.stringify(r)));
  }
}
"

